```

```javascript
const cells = new Set();
cells.add(`${r},${c}`);  // "1,2" matches any later "1,2"
```

example.code:
const nums = [4, 2, 7, 2, 4];
const points = [[1, 2], [3, 4], [1, 2]];

function firstRepeat(values) {
  const seen = new Set();
  for (const value of values) {
    if (seen.has(value)) {
      return value;
    }
    seen.add(value);
  }
  return null;
}

function firstSeenLetters(word) {
  let result = "";
  for (const letter of new Set(word)) {
    result += letter;
  }
  return result;
}

function sortedLetters(word) {
  return Array.from(new Set(word)).sort((a, b) => a.localeCompare(b)).join(" ");
}

function distinctKeys(pairs) {
  const keys = new Set();
  for (const [x, y] of pairs) {
    keys.add(`${x},${y}`);
  }
  return keys;
}

console.log(`first repeat: ${firstRepeat(nums)}`);
console.log(`first seen: ${firstSeenLetters("banana")}`);
console.log(`sorted: ${sortedLetters("banana")}`);
console.log(`array set: ${new Set(points).size}`);

const keys = distinctKeys(points);
console.log(`key set: ${keys.size}`);
keys.forEach((key) => {
  console.log(`point ${key}`);
});

