steps.body:
Node 20 has no built-in `union()`, `intersection()`, or `difference()` on sets. Those methods arrived in Node 22, and calling `a.union(b)` here throws a TypeError. Build each one from spread, `filter`, and `has`:

```javascript harness
const a = new Set(["dev", "ana", "ben", "cara"]);
const b = new Set(["cara", "fay", "ana", "eli"]);
const small = new Set(["ben", "dev"]);
const big = a;
{{code}}
console.log(`union: ${[...union].join(", ")}`);
console.log(`both: ${both.join(", ")}`);
console.log(`onlyA: ${onlyA.join(", ")}`);
console.log(`isSubset: ${isSubset}`);
```

```javascript
const union = new Set([...a, ...b]);                  // in a or b
const both = [...a].filter((x) => b.has(x));          // in a and b
const onlyA = [...a].filter((x) => !b.has(x));        // in a, not in b
const isSubset = [...small].every((x) => big.has(x)); // all of small in big
```

Spread the first set into an array so you can call `filter` and `every`, then test the other side with `has`, which is fast. Difference is one-sided: `a` minus `b` is not the same as `b` minus `a`.

Results follow the insertion order of the set you spread first. When the output should be sorted, sort the array before you join it.

example.code:
const math = new Set(["dev", "ana", "ben", "cara"]);
const art = new Set(["cara", "fay", "ana", "eli"]);
const studyGroup = new Set(["ben", "dev"]);

function union(a, b) {
  return new Set([...a, ...b]);
}

function intersection(a, b) {
  return new Set([...a].filter((x) => b.has(x)));
}

function difference(a, b) {
  return new Set([...a].filter((x) => !b.has(x)));
}

function isSubset(small, big) {
  return [...small].every((x) => big.has(x));
}

function show(set) {
  return [...set].sort((a, b) => a.localeCompare(b)).join(", ");
}

console.log(`either: ${show(union(math, art))}`);
console.log(`both: ${show(intersection(math, art))}`);
console.log(`only math: ${show(difference(math, art))}`);
console.log(`group in math: ${isSubset(studyGroup, math)}`);
console.log(`group in art: ${isSubset(studyGroup, art)}`);

